package selfcheck
import("testing";"task143-batchreactor/internal/forecast";"task143-batchreactor/internal/lifecycle";"task143-batchreactor/internal/model";"task143-batchreactor/internal/report")
func TestBug08_ExactConversionSpecCanRelease(t *testing.T){b:=model.Batch{Status:model.BatchDischarging,Conversion:.9};if n,e:=lifecycle.NextStatus(b,model.BatchCleaning,&lifecycle.TransitionContext{MinConversion:.9});e!=nil||n!=model.BatchCleaning{t.Fatalf("exact conversion release=%s err=%v",n,e)};r:=exothermicRecipe();r.MinConversion=.9;f:=forecast.Build(forecast.Input{Batch:model.Batch{ID:"b",Status:model.BatchDischarging},Recipe:r,Reactor:safeReactor(),Result:&model.SafetyResult{Conversion:.9,Verdict:model.VerdictSafe},Now:1});if f.ConversionGap!=0{t.Fatalf("gap=%v",f.ConversionGap)};a:=report.Build(report.Input{Forecasts:[]model.BatchForecast{f},Now:1});if len(a.Warnings)!=0{t.Fatalf("warnings=%v",a.Warnings)}}
